"""Reading records."""


class Reading:
    def __init__(self, sensor, level):
        self.sensor = sensor
        self.level = level

    def __repr__(self):
        return "Reading(%r, %r)" % (self.sensor, self.level)


ROWS = [('south', 18), ('east', 53), ('east', 10), ('south', 6), ('south', 20), ('north', 25)]


def load_readings():
    """Yield the stored readings one at a time."""
    for sensor, level in ROWS:
        yield Reading(sensor, level)


def feed_readings():
    """Endless feed of readings: repeats the stored rows for ever."""
    while True:
        for sensor, level in ROWS:
            yield Reading(sensor, level)

