"""Windows over the readings feed."""
import itertools


def summarize_window(feed, size):
    """Read the next `size` readings from the feed and return (peak level, list of level).

    The feed may be endless. Exactly `size` items are read from it.
    """
    window = itertools.islice(feed, size)
    peak = max(x.level for x in window)
    values = [x.level for x in window]
    return peak, values


def group_by_sensor(readings):
    """Return a dict from sensor to the list of readings with that sensor."""
    groups = {}
    for x in readings:
        groups.setdefault(x.sensor, []).append(x)
    return groups


def sensor_names(readings):
    """Return the distinct sensor values, in first-seen order."""
    names = []
    for x in readings:
        if x.sensor not in names:
            names.append(x.sensor)
    return names
